const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID(), today=()=>localDate(new Date()),localDate=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`, addDays=(date,n)=>{let d=new Date(date+'T12:00:00');d.setDate(d.getDate()+n);return localDate(d)}, fmt=n=>n>=60?`${Math.floor(n/60)} h${n%60?' '+String(n%60).padStart(2,'0'):''}`:`${n} min`, euro=n=>Number(n).toLocaleString('fr-FR',{style:'currency',currency:'EUR',maximumFractionDigits:0});
const cats={'etsy':'Etsy & numérique','print':'Impression 3D','dev':'Dev & automatisation','general':'Exploration'};
const ideas=[{id:'etsy',symbol:'✳',title:'Un premier produit numérique',desc:'Créer un petit outil utile : planner, suivi de budget ou modèle de tableau. Une niche, un besoin, un prototype.',budget:'Test possible sans stock',time:'4 h 15 pour un premier test',steps:[['Choisir une niche et noter 5 besoins concrets',30,'Liste les usages et les solutions existantes. Cherche un problème précis, pas simplement un joli visuel.'],['Définir un produit et demander 3 retours',30,'Prépare une description et contacte des personnes concernées. Note leurs objections avant de créer.'],['Créer un prototype de produit numérique',90,'Crée un contenu original dont tu possèdes les droits. Teste les fichiers et la notice.'],['Préparer les visuels et le calcul de marge',60,'Liste prix envisagé, frais à vérifier sur la plateforme, outils et temps de support.'],['Préparer puis publier une fiche test',45,'Vérifie les règles et frais actuels avant publication. Suis les visites, questions et premières ventes.']]},{id:'print',symbol:'⬡',title:'La 3D, avant la machine',desc:'Valider un besoin et chiffrer un objet avec un prestataire. Investir seulement après des signaux concrets.',budget:'Aucune imprimante nécessaire',time:'2 h 45 pour valider une piste',steps:[['Lister 5 problèmes résolvables en impression 3D',25,'Petites pièces utiles, rangement ou gabarits. Évite les pièces critiques pour la sécurité.'],['Dessiner une pièce simple ou choisir un modèle autorisé',50,'Vérifie la licence commerciale. Fais un croquis coté ou un modèle prêt à faire chiffrer.'],['Demander 2 devis de fabrication externe',30,'Demande prix, matière, délai et livraison. Aucun achat nécessaire à cette étape.'],['Calculer le coût complet d’une pièce',30,'Fabrication, emballage, transport, frais, défauts et ton temps. Fixe une marge cible.'],['Présenter le concept à 3 acheteurs potentiels',30,'Recueille besoin, budget et objections sans promettre de livraison non maîtrisée.']]},{id:'dev',symbol:'⌘',title:'Vendre une automatisation utile',desc:'Partir de tes compétences Excel et web pour proposer une petite mission, claire et facile à comprendre.',budget:'Tes compétences déjà disponibles',time:'3 h pour lancer une offre',steps:[['Définir une offre d’automatisation précise',30,'Exemple : fiabiliser un fichier Excel répétitif. Décris le livrable, les limites et le délai.'],['Créer une démo avec des données fictives',75,'Montre un avant/après concret. Utilise tes propres données et ressources.'],['Lister 10 prospects avec un besoin plausible',30,'Renseigne une entreprise, un problème observé et le moyen de contact public.'],['Préparer 3 prises de contact personnalisées',30,'Un besoin observé, un exemple de résultat et une question courte. Envoi manuel.'],['Préparer un cadre de devis simple',15,'Périmètre, délai, prix envisagé et conditions à préciser avant accord.']]},{id:'general',symbol:'↗',title:'Tester une nouvelle piste',desc:'Structurer une idée personnelle en expérience courte. Décider ensuite de continuer, ajuster ou arrêter.',budget:'Budget de test à définir',time:'1 h 30 pour cadrer le test',steps:[['Décrire le client et son problème',20,'Qui paierait, pour quoi et pourquoi maintenant ?'],['Choisir le test le plus simple',25,'Un prototype ou une conversation peut suffire. Fixe une limite de temps et de dépenses.'],['Recueillir 3 retours concrets',30,'Privilégie les signaux observables : demande de prix, rendez-vous, devis.'],['Faire le bilan et décider de la suite',15,'Continue, ajuste ou archive. Le temps économisé est aussi un résultat.']]}];
const task=(title,cat,min,extra={})=>({id:uid(),title,cat,min,date:today(),repeat:'none',priority:'normal',note:'',...extra});
let state;try{state=JSON.parse(localStorage.getItem('elan-v1'))}catch{}if(!state||!Array.isArray(state.tasks))state={tasks:[task('Choisir le premier besoin à résoudre','dev',30,{priority:'high',note:'Une petite automatisation Excel ou web, un client précis et un résultat visible.'}),task('Explorer une niche pour un produit numérique','etsy',30,{note:'Note 5 problèmes concrets avant de commencer la création.'}),task('Lister 3 objets utiles à tester en 3D','print',25,{note:'Sans machine : croquis, modèle autorisé et devis de sous-traitance.'}),task('Identifier 3 prospects et personnaliser une approche','dev',25,{repeat:'weekly',date:addDays(today(),1),note:'Renseigne les contacts dans Prospection. Aucun message n’est envoyé automatiquement.'})],history:[],contacts:[],ledger:[],activated:[],settings:{budget:90,goal:300,hours:5}};
state.history??=[];state.contacts??=[];state.ledger??=[];state.activated??=[];state.settings??={budget:90,goal:300,hours:5};
let view='plan',filter='today',category='all',search='',timer=null,toastTimeout;
function save(){try{localStorage.setItem('elan-v1',JSON.stringify(state))}catch{toast('Sauvegarde impossible : exporte tes données depuis les réglages.')}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').style.display='none',4200)}
const icons={plan:'<rect x="3" y="3" width="18" height="18" rx="3"/><path d="M8 3v18M12 8h5M12 12h5M12 16h3"/>',ideas:'<path d="M9 18h6m-5 3h4M8 14a6 6 0 1 1 8 0l-1 3H9z"/>',contacts:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m2 3a5 5 0 0 1 3 5v2"/>',stats:'<path d="M3 3v18h18M7 16l5-6 4 2 5-7M16 5h5v5"/>'};const icon=k=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[k]}</svg>`;const labels={plan:['◫','Mon plan d’action'],ideas:['✳','Pistes de revenus'],contacts:['◎','Prospection'],stats:['↗','Mes résultats']};
function render(){save();$('#nav').innerHTML=Object.entries(labels).map(([k,v])=>`<button data-view="${k}" class="${view===k?'active':''}"><span class="ico">${icon(k)}</span>${v[1]}${k==='plan'?`<small>${state.tasks.filter(t=>t.date<=today()).length}</small>`:''}</button>`).join('');$('#pageName').textContent=labels[view][1];$('#content').innerHTML=({plan:renderPlan,ideas:renderIdeas,contacts:renderContacts,stats:renderStats}[view])();}
function intro(k,title,sub,button=''){return `<div class="intro"><div><div class="kicker">${k}</div><h1>${title}</h1><p class="sub">${sub}</p></div>${button}</div>`}
function metrics(items){return `<div class="metrics">${items.map(([l,n,s,a])=>`<div class="metric"><label>${l}</label><strong class="${a?'accent':''}">${n}</strong><small>${s}</small></div>`).join('')}</div>`}
function tag(c){return `<span class="tag ${c}">${cats[c]||'Exploration'}</span>`}
function taskRow(t){return `<article class="task"><button class="check" data-done="${t.id}" aria-label="Terminer : ${esc(t.title)}"></button><div class="task-info"><button class="task-title" data-edit="${t.id}">${esc(t.title)}</button><div class="task-meta">${tag(t.cat)}${t.priority==='high'?'<span style="color:#c07846">● Prioritaire</span>':''}<span>${t.date<today()?'En retard · ':''}${new Date(t.date+'T12:00:00').toLocaleDateString('fr-FR',{day:'numeric',month:'short'})}</span>${t.repeat!=='none'?`<span>↻ ${repeatName[t.repeat]}</span>`:''}<button class="quiet" style="padding:0;font-size:10px" data-focus="${t.id}">▷ Se concentrer</button></div></div><span class="task-time">◷ ${fmt(t.min)}</span></article>`}
const repeatName={none:'Une seule fois',daily:'Chaque jour',weekdays:'Jours ouvrés',weekly:'Chaque semaine',monthly:'Chaque mois'};
function renderPlan(){let due=state.tasks.filter(t=>t.date<=today()),done=state.history.filter(h=>h.date===today()),used=done.reduce((s,h)=>s+h.actual,0),remaining=Math.max(0,state.settings.budget-used),net=state.ledger.reduce((s,l)=>s+(l.type==='income'?l.amount:-l.amount),0);let list=state.tasks.filter(t=>(filter==='all'||filter==='today'&&t.date<=today()||filter==='week'&&t.date<=addDays(today(),6))&&(category==='all'||t.cat===category)&&t.title.toLowerCase().includes(search.toLowerCase())).sort((a,b)=>a.date.localeCompare(b.date)||(b.priority==='high')-(a.priority==='high'));return intro('À TON RYTHME, EMMANUEL','Une idée. <em>Un premier pas.</em>','Ton temps est précieux. Donnons une direction à tes projets.',`<button class="primary" data-new>＋ Nouvelle tâche</button>`)+`<section class="hero"><div><div class="kicker">LE BON RÉFLEXE</div><h2>Avant de produire,<br>trouve le besoin.</h2><p>Une conversation, un prototype, un premier retour.<br>Cette semaine, fais avancer une seule piste jusqu’au test.</p><button data-view="ideas">Explorer les pistes <span style="margin-left:18px">↗</span></button></div><div class="art" aria-hidden="true"><div class="orb"><svg viewBox="0 0 100 100"><path d="M20 75 75 20M28 20h47v47"/></svg></div><small>FAIRE GRANDIR L’IDÉE</small></div></section>`+metrics([['À faire aujourd’hui',due.length,`${fmt(due.reduce((s,t)=>s+t.min,0))} estimées`],['Temps disponible',fmt(remaining),'sur ton budget quotidien'],['Actions réalisées',state.history.length,`${done.length} aujourd’hui`],['Résultat net saisi',euro(net),'encaissements − dépenses',true]])+`<div class="layout"><section><div class="section-head"><h2>Les prochaines actions <span style="color:#999e8f;font-size:12px;margin-left:5px">${list.length}</span></h2><button class="quiet" data-auto style="font-size:11px">✧ Composer ma session</button></div><div class="filters">${[['today','Aujourd’hui'],['week','7 prochains jours'],['all','Toutes les tâches']].map(([k,v])=>`<button data-filter="${k}" class="${filter===k?'active':''}">${v}</button>`).join('')}</div><div class="toolbar"><input id="search" class="search" placeholder="Rechercher une tâche…" aria-label="Rechercher" value="${esc(search)}"><select id="catFilter" aria-label="Filtrer par piste"><option value="all">Toutes les pistes</option>${Object.entries(cats).map(([k,v])=>`<option value="${k}" ${k===category?'selected':''}>${v}</option>`).join('')}</select></div><div id="tasklist">${list.map(taskRow).join('')||'<div class="empty">Tout est au clair pour cette sélection.<br>Ajoute une action ou explore une nouvelle piste.</div>'}</div></section><div class="rightcol"><section class="panel"><div class="panel-top"><h3>Ton cap personnel</h3><span>⚑</span></div><p>Objectif de revenus encaissés<br><strong style="font-size:23px;color:#414e37">${euro(state.settings.goal)}</strong> <span>/ mois</span></p>${goalProgress()}<button class="secondary" data-settings>Ajuster mon objectif ↗</button></section><section class="panel" style="background:#f0e9de"><div class="kicker" style="color:#9e7954">SANS IMPRIMANTE, DÉJÀ DANS L’ACTION</div><h3 style="margin-top:12px">La 3D commence par un besoin.</h3><p>Fais chiffrer une pièce et interroge ses futurs utilisateurs avant d’acheter du matériel.</p><button class="quiet" style="padding:0;font-size:11px;color:#9e7954" data-activate="print">Voir le plan de test →</button></section><div class="little-tip"><b>✧ Une estimation qui évolue</b><br>Note ton temps réel en terminant. Les prochaines estimations pourront s’appuyer sur ton rythme.</div></div></div>`}
function monthIncome(){return state.ledger.filter(l=>l.type==='income'&&l.date.slice(0,7)===today().slice(0,7)).reduce((s,l)=>s+l.amount,0)}function goalProgress(){let n=monthIncome(),p=Math.min(100,n/Math.max(1,state.settings.goal)*100);return `<div class="progress"><i style="width:${p}%"></i></div><div class="progress-label"><span>${euro(n)} encaissés ce mois</span><span>${Math.round(p)} %</span></div>`}
function renderIdeas(){return intro('LE LABORATOIRE','De l’intuition <em>au test.</em>','Des expériences courtes pour découvrir ce qui mérite ton énergie.')+`<div class="recap" style="margin:22px 0 27px">✧ Choisis une piste, teste la demande, puis décide. Les plans proposés sont des expériences à adapter ; ils ne promettent aucun revenu.</div><div class="grid">${ideas.map(i=>`<article class="idea"><div class="symbol">${i.symbol}</div>${tag(i.id)}<h3 style="margin-top:15px">${i.title}</h3><p>${i.desc}</p><div class="details">◷ ${i.time}<br>◇ ${i.budget}<br>↳ ${i.steps.length} actions concrètes</div><button class="${state.activated.includes(i.id)?'secondary':'primary'}" data-activate="${i.id}">${state.activated.includes(i.id)?'Voir le plan activé':'Découvrir ce plan'} ↗</button></article>`).join('')}</div>`}
function renderContacts(){let q=search.toLowerCase(),list=state.contacts.filter(c=>(c.name+' '+c.offer).toLowerCase().includes(q));return intro('CRÉER DES CONVERSATIONS','Les contacts font <em>la différence.</em>','Un besoin observé, une approche personnelle, une prochaine action.',`<button class="primary" data-contact>＋ Ajouter un prospect</button>`)+metrics([['Contacts identifiés',state.contacts.length,'ton réseau de possibilités'],['À relancer',state.contacts.filter(c=>c.follow&&c.follow<=today()&&!['won','lost'].includes(c.status)).length,'échéances arrivées'],['Échanges en cours',state.contacts.filter(c=>['sent','talk','quote'].includes(c.status)).length,'de l’approche au devis'],['Clients gagnés',state.contacts.filter(c=>c.status==='won').length,'à distinguer des encaissements',true]])+`<div class="toolbar"><input id="search" placeholder="Rechercher un contact ou un besoin…" value="${esc(search)}"></div>${list.map(c=>`<article class="list-card"><div class="contact-top"><div><strong>${esc(c.name)}</strong><p class="sub" style="font-size:12px;margin-top:7px">${esc(c.offer)}</p></div><span class="tag general">${statuses[c.status]}</span></div><p class="hint">${esc(c.channel||'Canal à préciser')} ${c.follow?' · Relance '+new Date(c.follow+'T12:00:00').toLocaleDateString('fr-FR'):''} ${c.value?' · Devis envisagé '+euro(c.value):''}</p>${c.note?`<p class="hint">${esc(c.note)}</p>`:''}<div class="contact-actions"><button class="secondary" data-contact="${c.id}">Modifier le suivi</button><button class="secondary" data-follow="${c.id}">＋ Tâche de relance</button><button class="quiet" data-message="${c.id}">Préparer un message ↗</button></div></article>`).join('')||'<div class="empty">Ton prochain projet commence peut-être par une conversation.<br>Ajoute un premier contact et le besoin que tu as repéré.</div>'}`}
const statuses={new:'À contacter',sent:'Contacté',talk:'En discussion',quote:'Devis envoyé',won:'Gagné',lost:'Sans suite'};
function renderStats(){let time=state.history.reduce((s,h)=>s+h.actual,0),income=state.ledger.filter(l=>l.type==='income').reduce((s,l)=>s+l.amount,0),cost=state.ledger.filter(l=>l.type==='expense').reduce((s,l)=>s+l.amount,0);return intro('APPRENDRE DE TES ESSAIS','Le progrès se <em>mesure.</em>','Du temps investi aux résultats réellement obtenus.',`<button class="primary" data-money>＋ Saisir un montant</button>`)+metrics([['Temps réellement passé',fmt(time),`${state.history.length} actions terminées`],['Revenus encaissés',euro(income),'montants que tu as saisis'],['Dépenses engagées',euro(cost),'outils, fabrication, services'],['Résultat net',euro(income-cost),time?`${euro((income-cost)/(time/60))} / heure investie`:'pas encore de temps enregistré',true]])+`<div class="stat-grid"><section class="panel"><h3>Où va ton énergie ?</h3>${Object.entries(cats).map(([k,v])=>{let n=state.history.filter(h=>h.cat===k).reduce((s,h)=>s+h.actual,0);return `<div class="barrow"><span>${v.split(' &')[0]}</span><div class="bar"><i style="width:${time?n/time*100:0}%"></i></div><span>${fmt(n)}</span></div>`}).join('')}<p>Ton temps réel est enregistré quand tu termines une action. Les estimations restent séparées.</p></section><section class="panel"><h3>Ton objectif du mois</h3><p><strong style="font-size:28px;color:var(--ink)">${euro(monthIncome())}</strong> / ${euro(state.settings.goal)}</p>${goalProgress()}<p>Le résultat net correspond aux montants saisis, avant impôts et cotisations non renseignés.</p></section><section class="list-card"><h3>Dernières actions terminées</h3>${state.history.slice().reverse().slice(0,20).map(h=>`<div class="history"><div>${esc(h.title)}<br><small>${h.date} · prévu ${fmt(h.estimate)}</small></div><div>${fmt(h.actual)}<br><button class="quiet" style="padding:5px 0;font-size:10px" data-undo="${h.id}">Annuler</button></div></div>`).join('')||'<p class="hint">Tes premières actions apparaîtront ici.</p>'}</section><section class="list-card"><h3>Journal financier</h3>${state.ledger.slice().reverse().map(l=>`<div class="history"><div>${esc(l.label)}<br><small>${l.date} · ${cats[l.cat]||'Général'}</small></div><div>${l.type==='income'?'+':'−'}${euro(l.amount)}<br><button class="quiet" style="padding:5px 0;font-size:10px" data-removemoney="${l.id}">Supprimer</button></div></div>`).join('')||'<p class="hint">Aucun revenu ou dépense fictif : à toi de renseigner les résultats.</p>'}</section></div>`}
function modal(title,body){$('#modalBody').innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="close" aria-label="Fermer" data-close>×</button></div>${body}`;if(!$('#modal').open)$('#modal').showModal()}
const options=(obj,value)=>Object.entries(obj).map(([k,v])=>`<option value="${k}" ${value===k?'selected':''}>${v}</option>`).join('');
function estimate(title,cat){let base=/créer|prototype|démo|modélis/i.test(title)?90:/publier|visuel|calcul|devis/i.test(title)?45:/relanc|contact|prospect/i.test(title)?25:30;let past=state.history.filter(h=>h.cat===cat&&h.estimate>0);if(past.length>=2)base=Math.round(base*past.reduce((s,h)=>s+h.actual/h.estimate,0)/past.length/5)*5;return Math.max(5,Math.min(480,base))}
function taskModal(id,defaults={}){let t=state.tasks.find(t=>t.id===id)||task('','general',30,defaults);modal(id?'Modifier l’action':'Une nouvelle action',`<form id="taskForm"><label>Une action concrète<input name="title" required maxlength="180" placeholder="Ex. Préparer 3 prises de contact" value="${esc(t.title)}"></label><label>Piste<select name="cat">${options(cats,t.cat)}</select></label><div class="row"><label>Temps estimé (minutes)<input name="min" type="number" min="1" max="10080" required value="${t.min}"></label><label>Échéance<input name="date" type="date" required value="${t.date}"></label></div><button type="button" class="secondary" id="estimate">✧ Estimer selon l’action et mon rythme</button><div class="row"><label>Répétition<select name="repeat">${options(repeatName,t.repeat)}</select></label><label>Priorité<select name="priority">${options({normal:'Normale',high:'Prioritaire'},t.priority)}</select></label></div><label>Notes / résultat attendu<textarea name="note">${esc(t.note)}</textarea></label><p class="hint">Estimation indicative, toujours modifiable. Une tâche récurrente crée sa prochaine échéance quand tu la termines.</p><div class="form-actions">${id?'<button type="button" class="danger" id="deleteTask">Supprimer</button>':'<span></span>'}<button class="primary">Enregistrer l’action</button></div></form>`);let f=$('#taskForm');$('#estimate').onclick=()=>{f.elements.min.value=estimate(f.elements.title.value,f.elements.cat.value);toast('Estimation indicative mise à jour'+(state.history.filter(h=>h.cat===f.elements.cat.value).length>=2?' selon tes temps réels.':'. Elle s’affinera après 2 actions de cette piste.'))};f.onsubmit=e=>{e.preventDefault();let d=Object.fromEntries(new FormData(f));d.title=d.title.trim();if(!d.title)return;d.min=Number(d.min);if(id)Object.assign(t,d);else state.tasks.push({...t,...d});close();render();toast('Action enregistrée')};if(id)$('#deleteTask').onclick=()=>{state.tasks=state.tasks.filter(x=>x.id!==id);close();render();toast('Action supprimée')}}
function nextDate(t){let date=t.date;if(t.repeat==='monthly'){let d=new Date(date+'T12:00:00'),day=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+1);let max=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();d.setDate(Math.min(day,max));return localDate(d)}date=addDays(date,t.repeat==='weekly'?7:1);if(t.repeat==='weekdays')while([0,6].includes(new Date(date+'T12:00:00').getDay()))date=addDays(date,1);return date}
function doneModal(id,actual){let t=state.tasks.find(t=>t.id===id);if(!t)return;modal('Un pas de plus. Bien joué.',`<p class="sub">${esc(t.title)}</p><form id="doneForm" style="margin-top:20px"><label>Temps réellement passé (minutes)<input name="actual" type="number" required min="1" max="10080" value="${actual||t.min}"></label><p class="hint">Prévu : ${fmt(t.min)}.${t.repeat!=='none'?' Prochaine échéance : '+nextDate(t)+'. Si elle est encore passée, tu pourras la replanifier.':''}</p><button class="primary">Terminer l’action ✓</button></form>`);$('#doneForm').onsubmit=e=>{e.preventDefault();let snapshot={...t};let h={id:uid(),taskId:t.id,title:t.title,cat:t.cat,estimate:t.min,actual:Number(new FormData(e.target).get('actual')),date:today(),snapshot};state.history.push(h);if(t.repeat==='none')state.tasks=state.tasks.filter(x=>x.id!==id);else t.date=nextDate(t);close();render();toast('Action terminée'+(t.repeat!=='none'?' · prochaine échéance créée.':'.'))}}
function activate(id){let i=ideas.find(x=>x.id===id);modal(i.title,`<p class="sub">${i.desc}</p><div style="margin:22px 0">${i.steps.map((s,n)=>`<div class="history"><div><strong>${n+1}. ${s[0]}</strong><br><small>${s[2]}</small></div><span style="white-space:nowrap">${fmt(s[1])}</span></div>`).join('')}</div><p class="hint">Les actions sont réparties sur les prochains jours, à raison de ${state.settings.hours} h disponibles par semaine. Tu peux tout ajuster.</p><button class="primary" id="activatePlan">${state.activated.includes(id)?'Ouvrir mes actions':'Ajouter ce plan à mes actions'}</button>`);$('#activatePlan').onclick=()=>{if(!state.activated.includes(id)){let offset=0,load=0,daily=Math.max(15,Math.min(state.settings.budget,state.settings.hours*60/7));i.steps.forEach(([title,min,note])=>{if(load&&load+min>daily){offset++;load=0}state.tasks.push(task(title,id,min,{note,date:addDays(today(),offset)}));load+=min});state.activated.push(id);toast('Plan ajouté. Ajuste librement les échéances.')}category=id;filter='all';view='plan';close();render()}}
function contactModal(id){let c=state.contacts.find(x=>x.id===id)||{id:uid(),name:'',offer:'',channel:'',status:'new',value:0,follow:'',note:''};modal(id?'Suivre le contact':'Un nouveau contact',`<form id="contactForm"><label>Nom / entreprise<input name="name" required maxlength="150" value="${esc(c.name)}"></label><label>Besoin repéré / offre envisagée<input name="offer" required value="${esc(c.offer)}"></label><label>Canal ou coordonnées<input name="channel" placeholder="Email public, site, réseau…" value="${esc(c.channel)}"></label><div class="row"><label>Étape<select name="status">${options(statuses,c.status)}</select></label><label>Relance prévue<input name="follow" type="date" value="${c.follow}"></label></div><label>Devis envisagé (€) — optionnel<input name="value" type="number" min="0" value="${c.value}"></label><label>Notes<textarea name="note">${esc(c.note)}</textarea></label><p class="hint">Un devis envisagé ne compte pas comme un revenu. Les encaissements se saisissent dans Mes résultats.</p><div class="form-actions">${id?'<button type="button" class="danger" id="deleteContact">Supprimer</button>':'<span></span>'}<button class="primary">Enregistrer</button></div></form>`);$('#contactForm').onsubmit=e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));if(!d.name.trim()||!d.offer.trim())return;d.value=Number(d.value);if(id)Object.assign(c,d);else state.contacts.push({...c,...d});close();render()};if(id)$('#deleteContact').onclick=()=>{state.contacts=state.contacts.filter(x=>x.id!==id);close();render()}}
function settings(){modal('Un rythme qui te ressemble',`<form id="settingsForm"><div class="row"><label>Budget quotidien (minutes)<input name="budget" type="number" required min="10" max="1440" value="${state.settings.budget}"></label><label>Disponibilité (heures / semaine)<input name="hours" type="number" required min="0.5" max="100" step="0.5" value="${state.settings.hours}"></label></div><label>Objectif personnel encaissé / mois (€)<input name="goal" type="number" min="1" required value="${state.settings.goal}"></label><p class="hint">Un cap personnel, pas une prévision de gains. Les données sont conservées dans ce navigateur : exporte une sauvegarde pour les transférer sur un autre appareil.</p><button class="primary">Enregistrer mes préférences</button></form><hr style="border:0;border-top:1px solid var(--line);margin:25px 0"><h3>Tes données, avec toi</h3><div class="row"><button class="secondary" id="export">↓ Exporter la sauvegarde</button><button class="secondary" id="import">↑ Importer</button></div><input type="file" id="file" accept="application/json,.json" hidden><p class="hint">L’import remplace les données actuelles après confirmation. Aucun envoi automatique de messages ni de notifications en arrière-plan.</p>`);$('#settingsForm').onsubmit=e=>{e.preventDefault();state.settings=Object.fromEntries([...new FormData(e.target)].map(([k,v])=>[k,Number(v)]));close();render();toast('Ton rythme a été enregistré')};$('#export').onclick=()=>download();$('#import').onclick=()=>$('#file').click();$('#file').onchange=async e=>{try{let d=JSON.parse(await e.target.files[0].text());validateImport(d);modal('Importer cette sauvegarde ?',`<p class="sub">${d.tasks.length} tâches, ${d.contacts.length} contacts et ${d.history.length} actions terminées. Les données actuelles seront remplacées.</p><div class="form-actions"><button class="secondary" id="backupFirst">Exporter les données actuelles</button><button class="primary" id="confirmImport">Remplacer et importer</button></div>`);$('#backupFirst').onclick=download;$('#confirmImport').onclick=()=>{state=d;close();render();toast('Sauvegarde importée')}}catch{toast('Fichier invalide. Choisis une sauvegarde Élan valide.')}}}
function download(){let b=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download=`elan-sauvegarde-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function validateImport(d){const str=x=>typeof x==='string',num=x=>Number.isFinite(x)&&x>=0,date=x=>str(x)&&/^\d{4}-\d{2}-\d{2}$/.test(x)&&!isNaN(new Date(x+'T12:00:00'));if(!d||!['tasks','history','contacts','ledger','activated'].every(k=>Array.isArray(d[k]))||!d.settings||!['budget','hours','goal'].every(k=>num(d.settings[k])&&d.settings[k]>0))throw Error();let validTask=t=>t&&str(t.id)&&str(t.title)&&cats[t.cat]&&num(t.min)&&t.min>0&&date(t.date)&&repeatName[t.repeat]&&['normal','high'].includes(t.priority)&&str(t.note);if(!d.tasks.every(validTask)||!d.history.every(h=>str(h.id)&&str(h.title)&&cats[h.cat]&&num(h.actual)&&num(h.estimate)&&date(h.date)&&validTask(h.snapshot))||!d.contacts.every(c=>str(c.id)&&str(c.name)&&str(c.offer)&&str(c.channel)&&str(c.note)&&statuses[c.status]&&num(c.value)&&(!c.follow||date(c.follow)))||!d.ledger.every(l=>str(l.id)&&str(l.label)&&cats[l.cat]&&num(l.amount)&&date(l.date)&&['income','expense'].includes(l.type))||!d.activated.every(k=>cats[k]))throw Error()}
function money(){modal('Enregistrer un résultat réel',`<form id="moneyForm"><div class="row"><label>Type<select name="type"><option value="income">Revenu encaissé</option><option value="expense">Dépense</option></select></label><label>Montant (€)<input name="amount" type="number" required min="0.01" step="0.01"></label></div><label>Libellé<input name="label" required maxlength="180" placeholder="Ex. Première mission Excel"></label><div class="row"><label>Piste<select name="cat">${options(cats,'general')}</select></label><label>Date<input name="date" type="date" required value="${today()}"></label></div><button class="primary">Enregistrer le montant</button></form>`);$('#moneyForm').onsubmit=e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));if(!d.label.trim())return;d.amount=Number(d.amount);state.ledger.push({id:uid(),...d});close();render()}}
function session(){let done=state.history.filter(h=>h.date===today()).reduce((s,h)=>s+h.actual,0),available=Math.max(0,state.settings.budget-done),tasks=state.tasks.filter(t=>t.date<=today()).sort((a,b)=>(b.priority==='high')-(a.priority==='high')),selected=[],used=0;for(let t of tasks)if(used+t.min<=available){selected.push(t);used+=t.min}modal('Ta prochaine session',`<p class="sub">${fmt(available)} disponibles aujourd’hui. Priorité aux actions importantes qui tiennent dans ton créneau.</p><div style="margin:20px 0">${selected.map(taskRow).join('')||'<div class="empty">Aucune action ne tient dans ce créneau.<br>Découpe une tâche ou ajuste ton budget quotidien.</div>'}</div><p class="hint">${fmt(used)} planifiées · ${fmt(available-used)} de marge. Les tâches ne changent pas de date.</p>`)}
function focus(id){let t=state.tasks.find(x=>x.id===id);if(!t)return;if(timer&&timer.id!==id){toast('Une session est déjà en cours. Termine-la avant d’en démarrer une autre.');return}timer??={id,start:Date.now(),elapsed:0,running:true};modal('Une action, toute ton attention',`<p class="timer-title">${esc(t.title)}</p><div class="timer" id="clock">00:00</div><p class="hint" style="text-align:center">Objectif indicatif : ${fmt(t.min)} · Tu peux dépasser ce temps.</p><div class="timer-actions"><button class="secondary" id="pauseTimer"></button><button class="primary" id="finishTimer">Terminer</button></div><p class="hint" style="text-align:center">Le chrono continue si tu fermes cette fenêtre, tant que cette page reste ouverte.</p>`);updateClock();$('#pauseTimer').onclick=()=>{if(timer.running)timer.elapsed+=Date.now()-timer.start;else timer.start=Date.now();timer.running=!timer.running;updateClock()};$('#finishTimer').onclick=()=>{let min=Math.max(1,Math.round(timerElapsed()/60000));timer=null;doneModal(id,min)}}
const timerElapsed=()=>timer?timer.elapsed+(timer.running?Date.now()-timer.start:0):0;function updateClock(){if(!timer||!$('#clock'))return;let sec=Math.floor(timerElapsed()/1000);$('#clock').textContent=`${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`;$('#pauseTimer').textContent=timer.running?'Ⅱ Pause':'▷ Reprendre'}setInterval(updateClock,1000);window.addEventListener('beforeunload',e=>{if(timer){e.preventDefault();e.returnValue=''}});
function close(){$('#modal').close()}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;let d=b.dataset;if(d.view){view=d.view;search='';render();window.scrollTo({top:0,behavior:'smooth'})}else if('new'in d)taskModal();else if(d.edit)taskModal(d.edit);else if(d.done)doneModal(d.done);else if(d.focus)focus(d.focus);else if(d.filter){filter=d.filter;render()}else if(d.activate)activate(d.activate);else if('close'in d)close();else if('contact'in d)contactModal(d.contact||null);else if(d.follow){let c=state.contacts.find(x=>x.id===d.follow);taskModal(null,{title:`Relancer ${c.name}`,cat:'dev',min:15,date:c.follow||today(),note:c.offer})}else if(d.message){let c=state.contacts.find(x=>x.id===d.message),msg=`Bonjour,\n\nJ’ai repéré un besoin possible autour de ${c.offer}. Je travaille sur des solutions simples et concrètes pour ce type de sujet.\n\nEst-ce un problème que vous rencontrez ? Si oui, je serais ravi d’en discuter quelques minutes et de vous montrer un exemple adapté.\n\nBonne journée,\nEmmanuel`;modal('Un point de départ à personnaliser',`<p class="hint">Ajoute une observation précise sur ${esc(c.name)} et remplace toute affirmation qui ne correspond pas à ton travail.</p><textarea id="draft" style="min-height:240px">${esc(msg)}</textarea><p class="hint">Ce brouillon reste ici. Tu choisis de le modifier et de l’envoyer toi-même.</p><button class="secondary" id="copyMessage">Copier le brouillon</button>`);$('#copyMessage').onclick=async()=>{try{await navigator.clipboard.writeText($('#draft').value);toast('Brouillon copié')}catch{$('#draft').select();toast('Sélectionne puis copie le texte.')}}}else if('money'in d)money();else if('settings'in d||b.id==='settings')settings();else if('auto'in d)session();else if(d.undo){let i=state.history.findIndex(h=>h.id===d.undo),h=state.history[i];let existing=state.tasks.find(t=>t.id===h.taskId);if(existing)Object.assign(existing,h.snapshot);else state.tasks.push({...h.snapshot});state.history.splice(i,1);render();toast('Action réouverte, temps réel retiré.')}else if(d.removemoney){let l=state.ledger.find(x=>x.id===d.removemoney);modal('Supprimer cette écriture ?',`<p class="sub">${esc(l.label)} · ${euro(l.amount)}</p><div class="form-actions"><button class="secondary" data-close>Conserver</button><button class="danger" id="confirmDeleteMoney">Supprimer</button></div>`);$('#confirmDeleteMoney').onclick=()=>{state.ledger=state.ledger.filter(x=>x.id!==l.id);close();render()}}});
document.addEventListener('change',e=>{if(e.target.id==='catFilter'){category=e.target.value;render()}});document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;let pos=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)}});render();
